//**************************************************************************************************
//! Refresh success counter
//!
//! \note       This function is needed to make the code compact.
//!
//! \param[in]  inRet - success flag of the previous operation
//! \param[inout]  okCnt - success counter
//!
//! \return     RESULT_OK     - function succeeded,
//!             RESULT_NOT_OK - function NOT succeeded.
//**************************************************************************************************
STD_RESULT UpdateOkCnt(const STD_RESULT inRet, U32* const okCnt)
{
    STD_RESULT outRet = RESULT_NOT_OK;
    if(RESULT_OK==inRet)
    {
        (*okCnt)++;
        outRet = RESULT_OK;
    }
    return outRet;
} // end of UpdareOkCnt()


